// meta_capi -- send sales to Meta (Facebook / Instagram Ads) as Purchase events
// with the Conversions API, so ads that brought customers in get the credit.
// Docs: https://developers.facebook.com/docs/marketing-api/conversions-api
//
// Buttons
//   Test Meta Conversions API (Integrations tab)  reads the pixel/dataset name
//   Send sale to Meta Ads (sale details)          POST /{pixel}/events (event Purchase,
//                                                 action_source physical_store)
// Customer email/phone are SHA-256 hashed before they leave the connector, as Meta requires.

import { sale, sha256Hex } from './_util.js';

const graph = (env) => `https://graph.facebook.com/${String(env.META_GRAPH_VERSION || 'v23.0').trim()}`;

async function meta(env, method, path, body) {
  const url = new URL(graph(env) + path);
  url.searchParams.set('access_token', env.META_CAPI_TOKEN);
  const res = await fetch(url, { method, headers: body ? { 'Content-Type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined });
  const data = await res.json().catch(() => null);
  if (!res.ok) throw new Error(`Meta: ${data?.error?.error_user_msg || data?.error?.message || `error ${res.status}`}`);
  return data;
}

export default {
  id: 'meta_capi',
  name: 'Meta Conversions API',
  category: 'marketing',
  status: 'available',
  description: 'Send each sale to Meta (Facebook/Instagram Ads) as a Purchase event so ad results are measured.',
  docsUrl: 'https://developers.facebook.com/docs/marketing-api/conversions-api',
  secrets: [
    { name: 'META_PIXEL_ID', label: 'Pixel / dataset ID', hint: 'Events Manager -> your dataset -> Settings.' },
    { name: 'META_CAPI_TOKEN', label: 'Conversions API access token', hint: 'Events Manager -> Settings -> Conversions API -> Generate access token.' },
    { name: 'META_TEST_EVENT_CODE', label: 'Test event code', hint: 'Only while testing in Events Manager -> Test events. Remove it to send real events.', optional: true },
    { name: 'META_GRAPH_VERSION', label: 'Graph API version', hint: 'Leave empty for v23.0.', optional: true },
  ],
  actions: [
    {
      id: 'test', label: 'Test Meta Conversions API', placement: ['settings'], fields: [],
      async run({ env }) {
        const d = await meta(env, 'GET', `/${encodeURIComponent(env.META_PIXEL_ID)}?fields=name,id`);
        return { type: 'message', title: 'Meta is connected', text: `Dataset "${d.name || d.id}"${env.META_TEST_EVENT_CODE ? ' -- test mode (events show under Test events)' : ''}.` };
      },
    },
    {
      id: 'send_purchase', label: 'Send sale to Meta Ads', placement: ['transaction'],
      fields: [
        { name: 'email', label: 'Customer email (email or phone needed)', type: 'email' },
        { name: 'phone', label: 'Customer phone, with country code (e.g. 9779800000000)', type: 'tel' },
      ],
      async run({ env, context, store, fields }) {
        const tx = sale(context);
        const email = String(fields.email || '').trim().toLowerCase();
        const phone = String(fields.phone || '').replace(/\D/g, '');
        if (!email && !phone) throw new Error("Meta needs the customer's email or phone to match the sale.");
        const user_data = {};
        if (email) user_data.em = [await sha256Hex(email)];
        if (phone) user_data.ph = [await sha256Hex(phone)];
        const items = Array.isArray(tx.items) ? tx.items : [];
        const event = {
          event_name: 'Purchase',
          event_time: Math.floor(new Date(tx.createdAt || Date.now()).getTime() / 1000) || Math.floor(Date.now() / 1000),
          event_id: `stratek-${tx.id}`,
          action_source: 'physical_store',
          user_data,
          custom_data: { currency: tx.currency, value: Number(tx.amount), order_id: tx.id, contents: items.map((i) => ({ id: String(i.name).slice(0, 100), quantity: Number(i.qty) || 1, item_price: Number(i.price) || undefined })) },
        };
        const d = await meta(env, 'POST', `/${encodeURIComponent(env.META_PIXEL_ID)}/events`, { data: [event], ...(env.META_TEST_EVENT_CODE ? { test_event_code: env.META_TEST_EVENT_CODE } : {}) });
        await store.put(`tx:${tx.id}`, { sentAt: new Date().toISOString() });
        return { type: 'message', title: 'Sent to Meta', text: `Purchase of ${tx.currency} ${tx.amount} sent (${d.events_received ?? 1} event${env.META_TEST_EVENT_CODE ? ', test mode' : ''}).` };
      },
    },
  ],
};

modules.integrations/meta_catalog.js:
// meta_catalog -- keep a Facebook / Instagram Shop catalogue in step with the
// Stratek menu (Catalog Batch API).
// Docs: https://developers.facebook.com/docs/marketing-api/catalog-batch/
//
// Buttons (Integrations tab)
//   Test Meta Catalog        reads the catalogue name and product count
//   Sync menu to Facebook/Instagram Shop
//                            upserts every menu item that has a photo (Meta requires an
//                            image); items marked unavailable are "out of stock".
// Stratek sends the menu with the request (the connector can't read Stratek on its own).

import { toMinor } from './_util.js';

const graph = (env) => `https://graph.facebook.com/${String(env.META_GRAPH_VERSION || 'v23.0').trim()}`;

async function meta(env, method, path, body) {
  const url = new URL(graph(env) + path);
  url.searchParams.set('access_token', env.META_SYSTEM_USER_TOKEN);
  const res = await fetch(url, { method, headers: body ? { 'Content-Type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined });
  const data = await res.json().catch(() => null);
  if (!res.ok) throw new Error(`Meta: ${data?.error?.error_user_msg || data?.error?.message || `error ${res.status}`}`);
  return data;
}

export default {
  id: 'meta_catalog',
  name: 'Meta Catalog (Facebook & Instagram Shop)',
  category: 'commerce',
  status: 'available',
  description: 'Keep a Facebook/Instagram shop catalogue in step with the POS menu.',
  docsUrl: 'https://developers.facebook.com/docs/marketing-api/catalog-batch/',
  secrets: [
    { name: 'META_CATALOG_ID', label: 'Catalog ID', hint: 'Commerce Manager -> your catalogue -> Settings.' },
    { name: 'META_SYSTEM_USER_TOKEN', label: 'System user access token', hint: 'Business Settings -> System users -> Generate token with catalog_management.' },
    { name: 'META_SHOP_URL', label: 'Shop web address', hint: 'Link shown on each product (e.g. your website or Instagram). Leave empty to use Stratek.', optional: true },
    { name: 'META_GRAPH_VERSION', label: 'Graph API version', hint: 'Leave empty for v23.0.', optional: true },
  ],
  actions: [
    {
      id: 'test', label: 'Test Meta Catalog', placement: ['settings'], fields: [],
      async run({ env }) {
        const d = await meta(env, 'GET', `/${encodeURIComponent(env.META_CATALOG_ID)}?fields=name,product_count`);
        return { type: 'message', title: 'Meta Catalog is connected', text: `Catalogue "${d.name}" has ${d.product_count ?? '?'} products.` };
      },
    },
    {
      id: 'sync_menu', label: 'Sync menu to Facebook/Instagram Shop', placement: ['settings'], fields: [],
      context: ['menu'], // Stratek sends { menu: { currency, items: [...] } }
      async run({ env, context, claims }) {
        const menu = context?.menu;
        if (!menu || !Array.isArray(menu.items)) throw new Error('Run this from a shop\'s Integrations tab (it needs the shop\'s menu).');
        const currency = String(menu.currency || 'NPR').toUpperCase();
        const link = env.META_SHOP_URL || claims.iss || 'https://strateknepal.com';
        const withPhoto = menu.items.filter((i) => /^https:\/\//.test(i.photo || ''));
        if (!withPhoto.length) throw new Error('None of your menu items has a photo -- Meta needs one per product.');
        const requests = withPhoto.slice(0, 5000).map((i) => ({
          method: 'UPDATE',
          retailer_id: `stratek-${i.id}`,
          data: {
            name: String(i.name).slice(0, 150),
            description: String(i.description || i.name).slice(0, 5000),
            price: toMinor(i.price, currency),
            currency,
            availability: i.available === false ? 'out of stock' : 'in stock',
            condition: 'new',
            image_url: i.photo,
            url: link,
            ...(i.category ? { category: String(i.category).slice(0, 250) } : {}),
          },
        }));
        let sent = 0;
        for (let k = 0; k < requests.length; k += 1000) {
          await meta(env, 'POST', `/${encodeURIComponent(env.META_CATALOG_ID)}/batch`, { allow_upsert: true, requests: requests.slice(k, k + 1000) });
          sent += Math.min(1000, requests.length - k);
        }
        const skipped = menu.items.length - withPhoto.length;
        return { type: 'message', title: 'Menu sent to Meta', text: `${sent} product(s) sent${skipped ? `; ${skipped} skipped (no photo)` : ''}. Meta processes them in a few minutes -- check Commerce Manager.` };
      },
    },
  ],
};

modules.integrations/pathao.js:
// pathao -- book and track Pathao courier deliveries for a sale (Nepal).
// Uses the Pathao Merchant (courier) API. Credentials: Pathao Merchant ->
// Developer API ("Merchant API Credentials"), which also shows the API base URL.
//
// Buttons
//   Test Pathao (Integrations tab)     get a token, list your Pathao stores (to find the store ID)
//   Send with Pathao (sale details)    create a delivery order (cash to collect = sale total by default)
//   Track Pathao delivery (sale)       order status
//
// The access token is cached in the connector and renewed when it expires.

const P = '/aladdin/api/v1';

function base(env) {
  const b = String(env.PATHAO_BASE_URL || '').trim().replace(/\/+$/, '');
  if (!/^https:\/\//.test(b)) throw new Error('Set the Pathao API base URL (https://...) in Set up -- it is shown on Pathao Merchant -> Developer API.');
  return b;
}

async function call(url, opts, what) {
  const res = await fetch(url, opts);
  const data = await res.json().catch(() => null);
  if (!res.ok) {
    const errs = data?.errors ? Object.values(data.errors).flat().join(' ') : '';
    throw new Error(`Pathao ${what}: ${data?.message || `error ${res.status}`}${errs ? ` (${errs})` : ''}`);
  }
  return data;
}

async function token(env, store) {
  const cached = await store.get('token');
  if (cached?.access_token && cached.expiresAt > Date.now() + 60000 && cached.base === base(env) && cached.clientId === env.PATHAO_CLIENT_ID) return cached.access_token;
  const d = await call(`${base(env)}${P}/issue-token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify({ client_id: env.PATHAO_CLIENT_ID, client_secret: env.PATHAO_CLIENT_SECRET, username: env.PATHAO_USERNAME, password: env.PATHAO_PASSWORD, grant_type: 'password' }),
  }, 'sign-in');
  if (!d?.access_token) throw new Error('Pathao sign-in did not return a token. Check the credentials in Set up.');
  await store.put('token', { access_token: d.access_token, expiresAt: Date.now() + (Number(d.expires_in) || 3600) * 1000, base: base(env), clientId: env.PATHAO_CLIENT_ID });
  return d.access_token;
}

async function api(env, store, method, path, body, what) {
  const t = await token(env, store);
  return call(`${base(env)}${P}${path}`, {
    method,
    headers: { Authorization: `Bearer ${t}`, Accept: 'application/json', ...(body ? { 'Content-Type': 'application/json' } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  }, what);
}

export default {
  id: 'pathao',
  name: 'Pathao',
  category: 'delivery',
  status: 'available',
  description: 'Book and track Pathao courier deliveries for a sale.',
  docsUrl: 'https://merchant.pathao.com/courier/developer-api',
  secrets: [
    { name: 'PATHAO_BASE_URL', label: 'Pathao API base URL', hint: 'Shown on Pathao Merchant -> Developer API (starts with https://).' },
    { name: 'PATHAO_CLIENT_ID', label: 'Client ID', hint: 'Pathao Merchant -> Developer API -> Merchant API Credentials.' },
    { name: 'PATHAO_CLIENT_SECRET', label: 'Client secret' },
    { name: 'PATHAO_USERNAME', label: 'Pathao merchant login email' },
    { name: 'PATHAO_PASSWORD', label: 'Pathao merchant password' },
    { name: 'PATHAO_STORE_ID', label: 'Store ID', hint: 'Press "Test Pathao" on the Integrations tab after saving the other keys to see your store IDs.', optional: true },
  ],
  actions: [
    {
      id: 'test',
      label: 'Test Pathao',
      placement: ['settings'],
      fields: [],
      async run({ env, store }) {
        const d = await api(env, store, 'GET', '/stores', null, 'stores');
        const list = d?.data?.data || d?.data || [];
        const names = Array.isArray(list) ? list.map((s) => `${s.store_name || s.name} (ID ${s.store_id || s.id})`).join(', ') : '';
        return { type: 'message', title: 'Pathao is connected', text: names ? `Your stores: ${names}.${env.PATHAO_STORE_ID ? '' : ' Put the right store ID in Set up.'}` : 'Signed in, but no stores were returned. Create a store in the Pathao merchant panel.' };
      },
    },
    {
      id: 'create_delivery',
      label: 'Send with Pathao',
      placement: ['transaction'],
      fields: [
        { name: 'recipientName', label: 'Recipient name', type: 'text', required: true },
        { name: 'recipientPhone', label: 'Recipient phone', type: 'tel', required: true },
        { name: 'recipientAddress', label: 'Delivery address', type: 'text', required: true },
        { name: 'codAmount', label: 'Cash to collect (0 if paid)', type: 'number', required: true, default: 0 },
        { name: 'itemWeight', label: 'Weight (kg)', type: 'number', default: 0.5 },
        { name: 'note', label: 'Note for rider', type: 'text' },
      ],
      async run({ env, store, fields, context }) {
        const tx = context?.transaction || {};
        if (!tx.id) throw new Error('Open this from a sale.');
        if (!env.PATHAO_STORE_ID) throw new Error('Add your Pathao store ID in Set up (press "Test Pathao" to see it).');
        const existing = await store.get(`tx:${tx.id}`);
        if (existing?.consignmentId) return { type: 'status', title: 'Pathao', status: 'Already booked', text: `Consignment ${existing.consignmentId}. Use "Track Pathao delivery".` };
        const items = Array.isArray(tx.items) ? tx.items : [];
        const d = await api(env, store, 'POST', '/orders', {
          store_id: Number(env.PATHAO_STORE_ID),
          merchant_order_id: `STK-${tx.id}`,
          recipient_name: String(fields.recipientName).slice(0, 100),
          recipient_phone: String(fields.recipientPhone).replace(/[^\d+]/g, ''),
          recipient_address: String(fields.recipientAddress).slice(0, 220),
          delivery_type: 48,
          item_type: 2,
          item_quantity: Math.max(1, items.reduce((n, i) => n + (Number(i.qty) || 1), 0)),
          item_weight: Number(fields.itemWeight) > 0 ? Number(fields.itemWeight) : 0.5,
          amount_to_collect: Math.max(0, Math.round(Number(fields.codAmount) || 0)),
          item_description: items.map((i) => `${i.qty || 1} x ${i.name}`).join(', ').slice(0, 250) || `Sale ${tx.reference || tx.id}`,
          special_instruction: fields.note ? String(fields.note).slice(0, 250) : undefined,
        }, 'order');
        const o = d?.data || {};
        await store.put(`tx:${tx.id}`, { consignmentId: o.consignment_id, bookedAt: new Date().toISOString() });
        return { type: 'status', title: 'Pathao delivery booked', status: o.order_status || 'Pending', text: `Consignment ${o.consignment_id}${o.delivery_fee !== undefined ? `, delivery fee Rs ${o.delivery_fee}` : ''}.` };
      },
    },
    {
      id: 'track',
      label: 'Track Pathao delivery',
      placement: ['transaction'],
      fields: [],
      async run({ env, store, context }) {
        const id = context?.transaction?.id;
        const saved = id && (await store.get(`tx:${id}`));
        if (!saved?.consignmentId) return { type: 'message', title: 'Not booked', text: 'No Pathao delivery was booked for this sale.' };
        const d = await api(env, store, 'GET', `/orders/${encodeURIComponent(saved.consignmentId)}/info`, null, 'tracking');
        const o = d?.data || {};
        return { type: 'status', title: `Pathao ${saved.consignmentId}`, status: o.order_status || o.order_status_slug || 'Unknown', text: o.updated_at ? `Last update ${o.updated_at}.` : '' };
      },
    },
  ],
};

modules.integrations/paybridgenp.js:
// paybridgenp -- online payments through PayBridgeNP: one hosted checkout for
// eSewa, Khalti and Fonepay (Nepal). Docs: https://docs.paybridgenp.com
//
// Buttons
//   Test PayBridgeNP (Integrations tab)  GET /v1/account -- shows project + sandbox/live
//   Pay online (under the payment QR)     POST /v1/checkout -> QR of the checkout LINK: scan it
//                                        with the phone CAMERA (it opens a web page), then pick
//                                        eSewa/Khalti/Fonepay. Wallet-app scanners don't open links.
//   Fonepay QR (under the payment QR)     POST /v1/qr/fonepay -> a real Fonepay QR that any bank
//                                        or wallet app scans directly (eSewa too). Refreshes the
//                                        same session if pressed again (~3 min per QR, 30 min per
//                                        session). Live needs a PayBridgeNP Pro plan.
//   Check online payment (sale details)  GET /v1/sessions/:id -> paid / pending / failed
//   Refund online payment (sale details) POST /v1/refunds (Khalti automatic, eSewa manual
//                                        in their portal, Fonepay not supported)
//
// Amounts: Stratek sends rupees; PayBridgeNP wants paisa (x100), minimum Rs 10.
// After "Paid", the shop presses Settle in Stratek. (Automatic confirmation via
// signed webhooks comes with Stratek's signed-events update.)

const API = 'https://api.paybridgenp.com/v1';

async function pb(env, method, path, body, idempotencyKey) {
  const headers = { Authorization: `Bearer ${env.PAYBRIDGE_SECRET_KEY}`, Accept: 'application/json' };
  if (body) headers['Content-Type'] = 'application/json';
  if (idempotencyKey) headers['Idempotency-Key'] = idempotencyKey;
  const res = await fetch(API + path, { method, headers, body: body ? JSON.stringify(body) : undefined });
  const data = await res.json().catch(() => null);
  if (!res.ok) {
    const msg = data?.error?.message || data?.message || (typeof data?.error === 'string' ? data.error : null);
    if (res.status === 401) throw new Error('PayBridgeNP did not accept the secret key. Check it in Set up.');
    if (res.status === 403) throw new Error(`This PayBridgeNP key is missing a permission${msg ? `: ${msg}` : ''}.`);
    throw new Error(`PayBridgeNP: ${msg || `error ${res.status}`}`);
  }
  return data;
}

const saleId = (context) => {
  const id = context?.transaction?.id;
  if (!id) throw new Error('Open this from a sale.');
  return String(id);
};

// Test-mode logins from PayBridgeNP's sandbox guide. The real eSewa/Khalti apps
// can't pay test payments -- they use the providers' test websites.
const TEST_NOTE = ' TEST mode: eSewa and Khalti only accept their test accounts here (eSewa ID 9806800001, password Nepal@123, MPIN 1122, OTP 123456; Khalti ID 9800000005, MPIN 1111, OTP 987654) -- the real apps cannot pay test payments. Fonepay in test mode is real money (max Rs 1,000).';

const STATUS = {
  success: ['Paid', 'The customer has paid online. Now press Settle on this sale.'],
  pending: ['Waiting', 'The customer has not paid yet.'],
  initiated: ['In progress', 'The customer started paying but has not finished.'],
  failed: ['Failed', 'The payment failed. You can start a new one from the charge screen.'],
  cancelled: ['Cancelled', 'The customer cancelled the payment.'],
  expired: ['Expired', 'The payment link expired. Start a new one if needed.'],
};

export default {
  id: 'paybridgenp',
  name: 'PayBridgeNP',
  category: 'payments',
  status: 'available',
  description: 'eSewa, Khalti and Fonepay in one online checkout (Nepal).',
  docsUrl: 'https://docs.paybridgenp.com/api-reference/overview',
  secrets: [
    { name: 'PAYBRIDGE_SECRET_KEY', label: 'PayBridgeNP secret key', hint: 'From your PayBridgeNP dashboard. Starts with sk_live_ (or sk_test_ for testing -- note Fonepay has no sandbox, test payments move real money).' },
  ],
  actions: [
    {
      id: 'test',
      label: 'Test PayBridgeNP',
      placement: ['settings'],
      fields: [],
      async run({ env }) {
        const a = await pb(env, 'GET', '/account');
        const mode = a?.project?.mode === 'sandbox' ? 'TEST (sandbox)' : 'LIVE';
        return { type: 'message', title: 'PayBridgeNP is connected', text: `${a?.merchant?.name || 'Account'} -- project "${a?.project?.name || '?'}", ${mode} mode.` };
      },
    },
    {
      id: 'payment_link',
      label: 'Pay online (eSewa / Khalti / Fonepay)',
      placement: ['charge'],
      fields: [],
      async run({ env, context, origin, store, claims }) {
        const tx = context?.transaction || {};
        const id = saleId(context);
        if (tx.currency && tx.currency !== 'NPR') throw new Error('PayBridgeNP only takes payments in NPR.');
        const paisa = Math.round(Number(tx.amount) * 100);
        if (!Number.isFinite(paisa) || paisa < 1000) throw new Error('Online payments need at least Rs 10.');
        const s = await pb(env, 'POST', '/checkout', {
          amount: paisa,
          currency: 'NPR',
          returnUrl: `${origin}/paid`,
          cancelUrl: `${origin}/paid`,
          description: `${claims.owner_name || 'Shop'} -- sale #${id}`.slice(0, 200),
          metadata: { stratek_transaction: id, reference: tx.reference || null },
        }, `stratek-${claims.aud}-${id}-${paisa}`);
        await store.put(`tx:${id}`, { sessionId: s.id, amount: paisa, createdAt: new Date().toISOString() });
        return {
          type: 'qr',
          title: `Pay online -- Rs ${(paisa / 100).toFixed(2)}`,
          text: `Customer scans this with the phone CAMERA (not a wallet app) -- it opens a payment page where they choose eSewa, Khalti or Fonepay. Then use "Check online payment" on the sale.${s.livemode === false ? TEST_NOTE : ''}`,
          qrPayload: s.checkout_url,
        };
      },
    },
    {
      id: 'fonepay_qr',
      label: 'Fonepay QR (scan in any bank or wallet app)',
      placement: ['charge'],
      fields: [],
      async run({ env, context, store, claims }) {
        const tx = context?.transaction || {};
        const id = saleId(context);
        if (tx.currency && tx.currency !== 'NPR') throw new Error('Fonepay only takes payments in NPR.');
        const paisa = Math.round(Number(tx.amount) * 100);
        if (!Number.isFinite(paisa) || paisa < 1000) throw new Error('Online payments need at least Rs 10.');
        const saved = await store.get(`tx:${id}`);
        let q;
        if (saved?.kind === 'fonepay' && saved.amount === paisa) {
          // Same sale pressed again: fresh QR for the same session (QRs last ~3 minutes).
          q = await pb(env, 'POST', `/qr/${encodeURIComponent(saved.sessionId)}/refresh`).catch(() => null);
        }
        if (!q) {
          q = await pb(env, 'POST', '/qr/fonepay', {
            amount: paisa,
            currency: 'NPR',
            customer: { name: String(claims.owner_name || 'Customer').slice(0, 100), email: claims.actor && String(claims.actor).includes('@') ? claims.actor : 'customer@example.com' },
            metadata: { stratek_transaction: id, reference: tx.reference || null },
          }, `stratek-fonepay-${claims.aud}-${id}-${paisa}-${Date.now() >> 20}`);
          await store.put(`tx:${id}`, { sessionId: q.id, amount: paisa, kind: 'fonepay', createdAt: new Date().toISOString() });
        }
        return {
          type: 'qr',
          title: `Fonepay QR -- Rs ${(paisa / 100).toFixed(2)}`,
          text: `Customer scans this in their bank app or eSewa/Khalti (Fonepay QR). It stays valid about 3 minutes -- press the button again for a fresh one. Then use "Check online payment" on the sale.${q.livemode === false ? ' TEST mode still moves real money for Fonepay (max Rs 1,000).' : ''}`,
          qrPayload: q.qr_message,
        };
      },
    },
    {
      id: 'check',
      label: 'Check online payment',
      placement: ['transaction'],
      fields: [],
      async run({ env, context, store }) {
        const id = saleId(context);
        const saved = await store.get(`tx:${id}`);
        if (!saved) return { type: 'message', title: 'No online payment', text: 'No PayBridgeNP payment was started for this sale.' };
        const s = await pb(env, 'GET', `/sessions/${encodeURIComponent(saved.sessionId)}`);
        if (s.paymentId && s.paymentId !== saved.paymentId) await store.put(`tx:${id}`, { ...saved, paymentId: s.paymentId, status: s.status });
        const [status, text] = STATUS[s.status] || [s.status, ''];
        return { type: 'status', title: 'PayBridgeNP', status, text: `${text} Amount Rs ${(s.amount / 100).toFixed(2)}${s.provider ? ` via ${s.provider}` : ''}.` };
      },
    },
    {
      id: 'refund',
      label: 'Refund online payment',
      placement: ['transaction'],
      fields: [
        { name: 'amount', label: 'Amount to refund (Rs, empty = all)', type: 'number' },
        { name: 'note', label: 'Note (optional)', type: 'text' },
      ],
      async run({ env, context, store, fields }) {
        const id = saleId(context);
        let saved = await store.get(`tx:${id}`);
        if (!saved) throw new Error('No PayBridgeNP payment was started for this sale.');
        if (!saved.paymentId) {
          const s = await pb(env, 'GET', `/sessions/${encodeURIComponent(saved.sessionId)}`);
          if (!s.paymentId) throw new Error('This sale has not been paid online, so there is nothing to refund.');
          saved = { ...saved, paymentId: s.paymentId };
          await store.put(`tx:${id}`, saved);
        }
        const amount = fields.amount ? Math.round(Number(fields.amount) * 100) : saved.amount;
        if (!Number.isFinite(amount) || amount <= 0 || amount > saved.amount) throw new Error('Refund amount must be more than 0 and at most the amount paid.');
        const r = await pb(env, 'POST', '/refunds', { paymentId: saved.paymentId, amount, reason: 'customer_request', notes: fields.note || undefined }, `stratek-refund-${saved.paymentId}-${amount}`);
        const text = r.status === 'requires_action'
          ? 'Recorded. eSewa refunds must be finished in the eSewa merchant portal.'
          : r.status === 'succeeded' ? 'Refunded.' : `Refund status: ${r.status}.`;
        return { type: 'status', title: 'PayBridgeNP refund', status: r.status, text: `${text} Rs ${(r.amount / 100).toFixed(2)}.` };
      },
    },
  ],
};

modules.integrations/paypal.js:
// paypal -- PayPal Checkout for international customers.
// Docs: https://developer.paypal.com/api/rest/
//
// Buttons
//   Test PayPal (Integrations tab)       gets an access token (sandbox or live)
//   Pay with PayPal (under the QR)       POST /v2/checkout/orders -> QR of the approval page
//   Check PayPal payment (sale details)  GET the order; if approved, capture it
//   Refund PayPal payment (sale details) POST /v2/payments/captures/:id/refund
// PayPal only accepts certain currencies (not NPR); the shop's currency must be one of them.

import { toDecimalString, sale } from './_util.js';

const CURRENCIES = new Set(['AUD', 'BRL', 'CAD', 'CNY', 'CZK', 'DKK', 'EUR', 'HKD', 'HUF', 'ILS', 'JPY', 'MYR', 'MXN', 'TWD', 'NZD', 'NOK', 'PHP', 'PLN', 'GBP', 'SGD', 'SEK', 'CHF', 'THB', 'USD']);
const base = (env) => (String(env.PAYPAL_MODE || 'live').trim().toLowerCase() === 'sandbox' ? 'https://api-m.sandbox.paypal.com' : 'https://api-m.paypal.com');

async function token(env, store) {
  const cached = await store.get('token');
  if (cached?.access_token && cached.expiresAt > Date.now() + 60000 && cached.base === base(env) && cached.clientId === env.PAYPAL_CLIENT_ID) return cached.access_token;
  const res = await fetch(`${base(env)}/v1/oauth2/token`, {
    method: 'POST',
    headers: { Authorization: `Basic ${btoa(`${env.PAYPAL_CLIENT_ID}:${env.PAYPAL_CLIENT_SECRET}`)}`, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'grant_type=client_credentials',
  });
  const d = await res.json().catch(() => null);
  if (!res.ok || !d?.access_token) throw new Error(`PayPal did not accept the client ID/secret${String(env.PAYPAL_MODE || '').toLowerCase() === 'sandbox' ? ' (sandbox)' : ' (live -- set Mode to "sandbox" for test keys)'}.`);
  await store.put('token', { access_token: d.access_token, expiresAt: Date.now() + (d.expires_in || 3000) * 1000, base: base(env), clientId: env.PAYPAL_CLIENT_ID });
  return d.access_token;
}

async function pp(env, store, method, path, body, requestId) {
  const headers = { Authorization: `Bearer ${await token(env, store)}`, 'Content-Type': 'application/json', Prefer: 'return=representation' };
  if (requestId) headers['PayPal-Request-Id'] = requestId;
  const res = await fetch(base(env) + path, { method, headers, body: body ? JSON.stringify(body) : undefined });
  const data = await res.json().catch(() => null);
  if (!res.ok) throw new Error(`PayPal: ${data?.details?.[0]?.description || data?.message || `error ${res.status}`}`);
  return data;
}

export default {
  id: 'paypal',
  name: 'PayPal',
  category: 'payments',
  status: 'available',
  description: 'PayPal checkout for international customers.',
  docsUrl: 'https://developer.paypal.com/api/rest/',
  secrets: [
    { name: 'PAYPAL_CLIENT_ID', label: 'PayPal client ID', hint: 'developer.paypal.com -> Apps & Credentials.' },
    { name: 'PAYPAL_CLIENT_SECRET', label: 'PayPal client secret' },
    { name: 'PAYPAL_MODE', label: 'Mode', hint: 'Type "sandbox" for test credentials; leave empty for live.', optional: true },
  ],
  actions: [
    {
      id: 'test', label: 'Test PayPal', placement: ['settings'], fields: [],
      async run({ env, store }) {
        await token(env, store);
        return { type: 'message', title: 'PayPal is connected', text: `Credentials accepted (${base(env).includes('sandbox') ? 'SANDBOX' : 'LIVE'}). PayPal accepts: ${[...CURRENCIES].join(', ')}.` };
      },
    },
    {
      id: 'payment_link', label: 'Pay with PayPal', placement: ['charge'], fields: [],
      async run({ env, context, origin, store, claims }) {
        const tx = sale(context);
        if (!CURRENCIES.has(tx.currency)) throw new Error(`PayPal does not accept ${tx.currency}.`);
        const value = toDecimalString(tx.amount, tx.currency);
        const o = await pp(env, store, 'POST', '/v2/checkout/orders', {
          intent: 'CAPTURE',
          purchase_units: [{ reference_id: tx.id, custom_id: tx.id, description: `${claims.owner_name || 'Shop'} -- sale #${tx.id}`.slice(0, 127), amount: { currency_code: tx.currency, value } }],
          payment_source: { paypal: { experience_context: { return_url: `${origin}/paid`, cancel_url: `${origin}/paid`, user_action: 'PAY_NOW' } } },
        }, `stratek-${claims.aud}-${tx.id}-${value}`);
        const link = (o.links || []).find((l) => l.rel === 'payer-action' || l.rel === 'approve');
        if (!link) throw new Error('PayPal did not return a payment page.');
        await store.put(`tx:${tx.id}`, { orderId: o.id, value, currency: tx.currency });
        return { type: 'qr', title: `Pay with PayPal -- ${tx.currency} ${value}`, text: 'Customer scans this to pay with PayPal. Then use "Check PayPal payment" on the sale.', qrPayload: link.href };
      },
    },
    {
      id: 'check', label: 'Check PayPal payment', placement: ['transaction'], fields: [],
      async run({ env, context, store }) {
        const tx = sale(context);
        const saved = await store.get(`tx:${tx.id}`);
        if (!saved) return { type: 'message', title: 'No PayPal payment', text: 'No PayPal payment was started for this sale.' };
        let o = await pp(env, store, 'GET', `/v2/checkout/orders/${encodeURIComponent(saved.orderId)}`);
        if (o.status === 'APPROVED') o = await pp(env, store, 'POST', `/v2/checkout/orders/${encodeURIComponent(saved.orderId)}/capture`, {}, `stratek-capture-${saved.orderId}`);
        const capture = o.purchase_units?.[0]?.payments?.captures?.[0];
        if (capture?.id) await store.put(`tx:${tx.id}`, { ...saved, captureId: capture.id });
        const paid = o.status === 'COMPLETED';
        return { type: 'status', title: 'PayPal', status: paid ? 'Paid' : o.status, text: paid ? 'The customer has paid with PayPal. Now press Settle on this sale.' : 'Not paid yet.' };
      },
    },
    {
      id: 'refund', label: 'Refund PayPal payment', placement: ['transaction'],
      fields: [{ name: 'amount', label: 'Amount to refund (empty = all)', type: 'number' }],
      async run({ env, context, store, fields }) {
        const tx = sale(context);
        const saved = await store.get(`tx:${tx.id}`);
        if (!saved?.captureId) throw new Error('No completed PayPal payment for this sale (press "Check PayPal payment" first).');
        const body = fields.amount ? { amount: { value: toDecimalString(fields.amount, saved.currency), currency_code: saved.currency } } : {};
        const r = await pp(env, store, 'POST', `/v2/payments/captures/${encodeURIComponent(saved.captureId)}/refund`, body, `stratek-refund-${saved.captureId}-${fields.amount || 'all'}`);
        return { type: 'status', title: 'PayPal refund', status: r.status, text: `Refund ${r.id}.` };
      },
    },
  ],
};

